{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the objective to maximize total profit (total revenue minus raw material costs minus operating costs), or is there a different goal such as maximizing total units produced or minimizing total cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the \"Operating Costs at Full Capacity\" figures fixed costs that are incurred regardless of how much the machine is used, or are they variable costs that scale proportionally with the actual machine hours utilized?"
  ],
  "rationale": "The response asks for a single policy classification (fixed vs. variable) regarding the operating costs, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a machine is used at all, do you pay the full operating cost even if it is used for only a tiny fraction of its capacity, or is there a minimum utilization threshold below which the cost is not incurred?"
  ],
  "rationale": "The response asks for a single policy choice regarding cost incurrence based on utilization, presented as an either/or question."
}

